/* Supplied pathway diagram reconciled with current brand and pending transfer rules. */
const academyPathwayRows=[
 {name:'Foundation',color:'blue',purpose:'Build confidence with data, AI and prompting.',ids:[21,18,19],note:'Suggested sequence: data foundations → AI with Python → prompt engineering. This is a recommended learning order, not an approved prerequisite chain.',outcome:'Analyze data, evaluate models and design effective prompts.'},
 {name:'Builder',color:'green',purpose:'Develop, connect and evaluate agent systems.',ids:[16,26,22],note:'#16 is an introductory developer route; #26 adds intensive systems practice. #22 is a data-platform specialization, not a compulsory next step after #26.',outcome:'Build tool-using agents, coordinated workflows and retrieval data platforms.'},
 {name:'Flagship engineering',color:'blue',purpose:'Develop production-oriented agent engineering depth.',ids:[15],note:'Entry may follow #16, #26 or the #17 pathway after an evidence review. #16 → #15 module recognition and #26 → #15 Weekends 3–5 waivers are proposed, not automatic.',outcome:'Produce an evaluated agent system, operational runbook and defensible capstone.'},
 {name:'Extended pathways',color:'slate',purpose:'Combine related learning into a longer professional journey.',ids:[17,24],note:'#17 packages #21, #18, #19, generative-AI applications and #16 (about 24 weeks). #24 combines #21, #18, #19 and #15 with an industry capstone (about 32 weeks). Shared learning is recognized once; do not add all component durations again.',outcome:'Build a coherent portfolio across foundations, applications and agent engineering.'},
 {name:'Business and product',color:'orange',purpose:'Apply AI to organizational change and product delivery.',ids:[20,23],note:'Parallel specializations: #20 focuses on business transformation; #23 on AI product management. Neither is established as a compulsory prerequisite for #25.',outcome:'Define use cases, product requirements, success measures and implementation plans.'},
 {name:'Leadership',color:'purple',purpose:'Lead adoption, governance and strategic implementation.',ids:[25],note:'#25 is a proposed 24-week leadership pathway built on #13 Courses 1–2 plus a practicum. The #13 dependency and proposed recognition from #20/#23 remain TBC.',outcome:'Defend an organizational AI implementation plan with governance and measurable value.'}
];
function pathwayMapCard(id){const p=findProgram(id);return `<a class="map-program" href="#program/${id}"><span class="eyebrow">PROGRAM ${id}</span><h3>${esc(p?.title||'Specification pending')}</h3><p>${esc(p?.length||'TBC')}</p><span class="text-link">View program →</span></a>`;}
pathways=function(){return heading('How the programs stack','Scholarion Academy · Twelve extended programs, connected by learning goals.')+`<section class="card prose"><p>Choose a pathway for your goal. The map preserves the supplied program IDs while distinguishing learning recommendations, bundled programs and proposed recognition of prior learning.</p><div class="row wrap"><span class="tag">Recommended learning sequence</span><span class="tag">Parallel specialization</span><span class="tag">Proposed waiver · approval required</span><span class="tag">Dependency TBC</span></div></section><div class="academy-pathway-map">${academyPathwayRows.map(r=>`<section class="map-row map-${r.color}"><header><h2>${r.name}</h2><p>${r.purpose}</p></header><div><div class="map-cards">${r.ids.map(pathwayMapCard).join('')}</div><p class="map-note">${r.note}</p></div><aside><h3>Learning destination</h3><p>${r.outcome}</p></aside></section>`).join('')}</div><section class="card prose"><h2>Connections and recognition</h2><div class="table-scroll"><table><thead><tr><th>Connection</th><th>Relationship</th><th>Status</th></tr></thead><tbody><tr><td>#21 → #18 → #19</td><td>Suggested foundation sequence</td><td>Advisory</td></tr><tr><td>#16 → #15</td><td>Source proposes recognition of Modules 1–6; exact equivalence requires review</td><td>Proposed</td></tr><tr><td>#26 → #15</td><td>Source proposes waiver of Weekends 3–5</td><td>Proposed</td></tr><tr><td>#26 → #1</td><td>Source proposes recognition of Weeks 1–8</td><td>TBC — #1–#14 dependencies unresolved</td></tr><tr><td>#17 → #15</td><td>Preparation pathway; no blanket waiver specified</td><td>Advisory</td></tr><tr><td>#13 → #25</td><td>Courses 1–2 plus leadership practicum</td><td>TBC — #13 specification missing</td></tr><tr><td>#20 / #23 → #25</td><td>Suggested leadership progression; credit not established</td><td>TBC</td></tr><tr><td>#15 → GC-AGAE</td><td>Legacy relationship shown in the source; no verified current credential record</td><td>TBC — no degree or graduate-credit claim</td></tr></tbody></table></div><p>All programs shown are non-credit professional training. A certificate indicates completion. No automatic academic credit, transfer or duplicate recognition is awarded. Durations are program estimates, not additive pathway completion guarantees.</p><div class="row wrap">${btn('Explore the 11 core programs','#academy',true)}${btn('Self-paced entry routes','#self-paced',true)}${btn('Full program catalog','#catalog',true)}</div></section>`;};
render();
